"""Summarise the catalogue generated by OverheadCatalogueTest; does not change runtime data."""
import collections
import gzip
import json
import pathlib

ROOT = pathlib.Path(__file__).resolve().parents[1]
REPORT = ROOT / "build/reports/overheads/catalogue.json"
DESTINATION = ROOT / "docs/overhead-audit.md"


def escape(value):
    return str(value).replace("|", "\\|").replace("\n", " ")


def main():
    report = json.loads(REPORT.read_text(encoding="utf-8"))
    with gzip.open(ROOT / "src/main/resources/com/bestgearsetup/wiki-monsters.json.gz", "rt", encoding="utf-8") as stream:
        snapshot = json.load(stream)
    monsters = report["monsters"]
    bosses = [monster for monster in monsters if monster["boss"]]
    priority = ["unknown attack data", "unverified special mode", "insufficient fire protection",
                "style / max-hit fallback", "ordinary damage estimate", "no blockable attack in snapshot", "encounter rule"]

    def basis(monster):
        present = {advice["classification"] for advice in monster["representativeAdvice"].values()}
        return next(category for category in priority if category in present)

    counts = collections.Counter(basis(monster) for monster in monsters)
    boss_counts = collections.Counter(basis(monster) for monster in bosses)
    sources = sorted({advice["source"] for monster in monsters for advice in monster["representativeAdvice"].values()
                      if advice.get("source")})
    lines = [
        "# Overhead catalogue audit", "",
        "Evaluated on 2026-10-13 against the bundled snapshot retrieved " + snapshot["retrievedUtc"][:10] + ".", "",
        f"**{report['variants']:,} monster variants, including {len(bosses):,} boss variants, were exercised across "
        f"{report['cases']:,} recommendation cases.** This checks every variant against three combat classes, "
        "four representative armour/shield profiles, Prayer levels 30/37/40/43/99, and automatic/adjacent/two-tile distance.", "",
        "The per-variant decisions, notes, attack labels and rule sources are in the "
        "[generated catalogue](../build/reports/overheads/catalogue.json). Rerun `OverheadCatalogueTest` and then "
        "`python tools/write_overhead_audit.py` to refresh this report. The generated catalogue lives in the build directory.", "",
        "## Coverage", "",
        "Counts below count each variant once. If its combat-class recommendations have different bases, "
        "the least certain basis wins. Encounter rules describe verified mechanics or a documented strategy, "
        "including conditional instructions; they are not a claim of mathematically optimal damage for every kit.", "",
        "| Basis | All variants | Boss variants |", "| --- | ---: | ---: |",
    ]
    lines += [f"| {category.capitalize()} | {counts[category]:,} | {boss_counts[category]:,} |" for category in priority]
    lines += ["", "## Corrections made", "",
              "- Added delayed-cue, projectile-impact, counted-cycle and phase rules for Jad, Nightmare/Phosani, "
              "Scurrius, Hydra, Hunllef, Muspah, Leviathan, Whisperer, Doom, Yama, Nex, Hueycoatl, Cerberus, "
              "Galvek, Maggot King, Manticores, Inferno blobs, demonic gorillas and tormented demons.",
              "- Distinguished timing: Manticore prayers must precede launch; Leviathan/Doom projectiles are "
              "checked at impact; Muspah's ordinary ranged attacks require the overhead at attack start and "
              "its magic wind-up requires the switch before launch. Counted cycles and boss forms have their own cues.",
              "- Corrected ranged/magic Vanguard prayers, the unprotectable P1 obelisk attacks, continuing "
              "Akkha attacks while damaging shadows, P3 Warden supporting attacks, and approach-to-melee assumptions.",
              "- Added equipment checks for KBD fire shields/two-handed weapons, Araxxor's choice of distant "
              "attack against weaker defence, and Sarachnis's aranea boots. Vorkath's equipment rule remains in place.",
              "- Added prayer-disabled Barbarian Assault and Earth Warrior Champion rules, Sol's timed parry, "
              "and warnings about special modes whose mechanics have not been verified.",
              "- Separated ranged-magic/ranged-melee accuracy from Magic/Melee protection, and magical-melee/" 
              "magical-ranged accuracy from Melee/Missiles protection. Explicit partial penetration scales blocked damage.",
              "", "## What the automated pass establishes", "",
              "Every matrix case returns a coherent recommendation or an explicit unknown: available prayers "
              "respect level boundaries, the named overhead belongs to its prayer list, and a mixed infobox "
              "does not create a switching recommendation without an encounter rule. Regression tests exercise "
              "timing instructions, equipment dependencies, different damage/accuracy types, fire compatibility, "
              "and preservation of search assumptions when result views are copied.", "",
              "This is an evaluation of the recommendation engine, not 563,400 live game fights or a complete "
              "DPS/kill-time optimisation search for every monster. The representative table uses one-handed "
              "weapons, plate armour plus an anti-dragon shield, 99 base combat levels, 99 Prayer and automatic distance. "
              "It does not represent the player's bank or actual owned setup.", "",
              "## Limits of generic advice", "",
              "The current snapshot omits melee/ranged attack bonuses and supplies synthetic equal attack weights. "
              "Generic recommendations therefore estimate missing bonuses as zero and do not establish actual "
              "attack frequencies. Infobox maximum hits may combine specials or multiple hits. Base defensive "
              "levels are used; potion/defensive-prayer boosts and equipment damage-reduction effects are not "
              "simulated. Attack timing, guaranteed hits, adaptive style selection, room companions, minigame "
              "restrictions and boss specials need encounter rules rather than an ordinary damage formula.", "",
              "Explicit distance is an assumption about maintained position. Mobile monsters can approach, "
              "and team tanking, kiting and invocation/mode choices can change the right overhead. Known "
              "approach, projectile-melee and phase exceptions are documented in their advice. Source links "
              "below identify rule references; they do not independently verify every variant or special mode.", "",
              "## Boss variants", "",
              "These are the snapshot's `boss=true` variants. Some other bosses/modes/minions are not tagged as "
              "bosses by the snapshot; all still appear in the complete catalogue and were included in the matrix.", "",
              "| Variant | Melee setup | Ranged setup | Magic setup | Basis |",
              "| --- | --- | --- | --- | --- |"]
    for monster in sorted(bosses, key=lambda item: item["name"]):
        advice = monster["representativeAdvice"]
        lines.append("| " + " | ".join(escape(value) for value in [monster["name"], advice["MELEE"]["summary"],
                     advice["RANGED"]["summary"], advice["MAGIC"]["summary"], basis(monster)]) + " |")
    lines += ["", "## Explicit gaps", "",
              "An unknown attack record is not interpreted as *None needed*. An unverified special mode is "
              "not allowed to borrow the standard boss's timing. Insufficient fire protection is a gear problem "
              "in this representative profile (for example, an anti-dragon shield is not a wyvern shield), "
              "not a finding that the monster's mechanics are unknown.", "",
              "| Variant | Gap | Detail |", "| --- | --- | --- |"]
    for monster in sorted(monsters, key=lambda item: item["name"]):
        category = basis(monster)
        if category not in priority[:3]:
            continue
        detail = next(advice["note"] for advice in monster["representativeAdvice"].values()
                      if advice["classification"] == category)
        lines.append("| " + " | ".join(escape(value) for value in [monster["name"], category, detail]) + " |")
    lines += ["", "## Encounter references", "",
              "The runtime rules attach these references to advice; the catalogue retains them for review.", ""]
    lines += [f"- [{url.split('/w/')[-1].replace('_', ' ')}]({url})" for url in sources]
    lines.append("")
    DESTINATION.write_text("\n".join(lines), encoding="utf-8")
    print(f"Wrote {DESTINATION.name}: {len(monsters)} variants, {len(bosses)} boss rows, {report['cases']} cases.")
    print(dict(counts))


if __name__ == "__main__":
    main()
